// Simple tiling function to start
export function calculateTilePosition(
  index: i32,
  gridSize: i32,
  tileSize: f32,
  offsetX: f32,
  offsetY: f32
): f32 {
  const row = index / gridSize;
  const col = index % gridSize;
  const x = (col as f32) * tileSize + offsetX;
  const y = (row as f32) * tileSize + offsetY;
  return x; // Just return x for now, we'll expand this
}

// Test function to verify WASM works
export function multiplyByTwo(n: i32): i32 {
  return n * 2;
}`}),e(r,{children:"Eirian: Now build the WASM:"}),e(s,{language:"bash",children:"npm run asbuild"}),t(r,{children:["This should create files in ",t(i,{children:[e(a,{}),"/build"]})," folder."]}),e(r,{children:t(i,{children:[e(o,{}),"Card: Load WASM in React App"]})}),t(r,{children:["Eirian: Now let's update your ",t(i,{children:[e(a,{}),"App.tsx"]})," to load and use the WASM:"]}),e(s,{language:"typescript",children:`// src/App.tsx
